  "a_sentences": [
    {
      "a_text": "Anspruch auf einen Assistenzbeitrag haben Versicherte, welchen eine Hilflosenentschädigung der Invalidenversicherung nach Art. 42 Abs. 1-4 ausgerichtet wird, die zu Hause leben und volljährig sind (Art. 42quater Abs. 1 IVG).",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Verwaltungsweisungen dürfen keine über Gesetz und Verordnung hinausgehenden Einschränkungen eines materiellen Rechtsanspruchs einführen.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Das standardisierte Vorgehen mittels FAKT2 entspricht dem Willen des Gesetzgebers.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Das Bundesgericht präzisierte, dass FAKT2 kein geeignetes Instrument zur Ermittlung des gesamten Hilfebedarfs im Bereich Erziehung und Kinderbetreuung ist.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Das Bundesgericht bestätigte jedoch, dass der Hilfebedarf anhand des standardisierten Instruments FAKT2 zu ermitteln ist.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Ein Assistenzbeitrag wird gewährt für Hilfeleistungen, die von der versicherten Person benötigt und regelmässig von einer natürlichen Person erbracht werden.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Die Vorinstanz trug den individuellen Gegebenheiten bereits genügend Rechnung.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Das Bundesgericht erachtete die Beschwerde als begründet und bestätigte die Verfügung der IV-Stelle des Kantons St. Gallen vom 7. Februar 2025.",
      "b_propositions": ["P8"]
    }
  ]
}
